 \zeta\epsilon=0 \\
 \end{array}
}

&

A_4:
\begin{xy}
(0,-3) *[o]+{1}="A", (6,1) *[o]+{2}="B", (6,9) *[o]+{3}="C", (12,-3) *[o]+{4}="D", 
\ar @<2pt>"A";"B"^{\alpha}
\ar @<2pt>"B";"A"^{\beta}
\ar @<2pt>"B";"C"^{\delta}
\ar @<2pt>"C";"B"^{\gamma}
\ar @<2pt>"B";"D"^{\epsilon}
\ar @<2pt>"D";"B"^{\zeta}
\end{xy}
{\tiny \begin{array}{c}
