{\tiny \begin{array}{c}
  \alpha\beta\alpha=\sigma\zeta \\
  \beta\alpha\beta=\gamma\delta\\
  \zeta\beta\alpha=0 \\
 \delta\alpha\beta=0 \\
 \beta\alpha\gamma=0 \\
 \alpha\beta\sigma=0 \\
