\end{xy}
{\tiny \begin{array}{c}
  \delta\alpha=\epsilon\beta \\
  \gamma\epsilon=\beta\sigma\\
 \alpha\sigma\beta=0 \\
 \epsilon\gamma\delta=0 \\
 \sigma\gamma\epsilon\gamma=0 \\

\end{array}
}
&
A_{10}:
\begin{xy}
(8,10) *[o]+{1}="A", (8,1) *[o]+{2}="B", (16,-5) *[o]+{3}="C", (0,-5) *[o]+{4}="D",
