\ar @(lu,ld) "A";"A"_{\alpha} 
\ar "B";"A"_{\sigma}
\ar "C";"B"_{\gamma}
\ar @<2pt>"A";"C"^{\beta}
\ar @<2pt>"C";"A"^{\delta }
\end{xy}
{\tiny \begin{array}{c}
\alpha\beta\gamma=0 \\
\alpha^2=\beta\delta \\
\delta\beta=0 \\
\sigma\alpha=0\\
\delta\alpha=\gamma\sigma\\
\end{array}
}\\



\end{array}
\]

\label{P main}
Assume that $\cha K\neq 2$.
\begin{enumerate} 
\item Let $A$ be a basic $K$-algebra. Then the following are equivalent.
\begin{enumerate}
\item $A$ is a standard nondomestic self-injective cellular algebra
 of polynomial growth.
\item $A$ is isomorphic to either $A_1(\lambda)$, $A_2(\lambda)$ 
$(\lambda\in K\setminus\{0,1\})$, $A_4$, $A_7$ or $A_{11}$.
\end{enumerate}

\item There is no non-standard nondomestic self-injective cellular algebra
 of polynomial growth. 
 \end{enumerate}

proposition.raw:
\label{D prop local}
The algebra $A(\lambda)$ is cellular if and only if $\lambda=1$. 
In other words, any standard local self-injective cellular algebras of domestic type is isomorphic to the Kronecker algebra $K[X,Y]/(X^2,Y^2)$.

{S}}]
\label{D Prop dom}
Let $A$ be a self-injective algebra. Then, the following statements are equivalent:
\begin{enumerate}
\item[(1)] $A$ is non-standard domestic of infinite type.
\item[(2)] $A\cong \Omega(T)$ for some Brauer graph $T$ with one loop.
\end{enumerate}

proof.raw:
Let $B$ be the following bound quiver algebra.
\[\begin{xy}
(0,0) *[o]+{1}="A", (10,0) *[o]+{2}="B",
\ar @(ru,rd) "B";"B"^{z}
\ar @<2pt> "A";"B"^{x}
