\ar @<1mm> "1";"2"^{\alpha_{2}}
\ar @<1mm> "2";"1"^{\beta_{2}}
\ar @<1mm> "2";"3"^{\alpha_{3}}
\ar @<1mm> "3";"2"^{\beta_{3}}
\ar @<1mm> "m-1";"m"^{\alpha_{n-1}}
\ar @<1mm> "m";"m-1"^{\beta_{n-1}}
\SelectTips{eu}{}
\ar @(ur,dr) "m";"m"^{\beta_n}
\ar @(dl,ul)"0";"0"^{\gamma}
\end{xy}\]
and $I$ is the ideal in $KQ_{T(n)}$ generated by 
\begin{enumerate}
\item $\alpha_i\alpha_{i+1}$, for $1\leq i\leq n-2$,
\item $\beta_{i+1}\beta_{i}$, for $1\leq i \leq n-1$,
\item $\beta_1\alpha_1$ and $\alpha_{n-1}\beta_n$,
\item $\alpha_{i}\beta_{i}-\beta_{i-1}\alpha_{i-1}$, for $3\leq i\leq n-1$,
\item $\alpha_{2}\beta_{2}-\beta_1\gamma\alpha_1$ and $\beta_n-\beta_{n-1}\alpha_{n-1}$,
\item $\gamma^2-\gamma\alpha_1\beta_1$ and $\gamma\alpha_1\beta_1+\alpha_1\beta_1\gamma$.
\end{enumerate}

Thus, only $v_2$ is exceptional, and we should follow the definition in \cite{BS}.}
, which is of multiplicity two. 
We assume the following:
\begin{itemize}
\item
There is an edge $a$ of $T$ which has endpoints $v_1$ and $u$.
\item
The vertex $v_1$ is different from $v_2$ and $v_1$ is not an endpoint of any other edge than $a$.
\item
Let $b$ be the direct successor of $a$ and $c$ the direct predecessor of $a$ in the cyclic ordering around $u$. 
Then, $b\ne a$ and $c\ne a$.
\item
The vertices $u$, $v_{1}$, $v_{2}$ and the edges $a$, $b$, $c$ determine a subtree 
\[ 
 \begin{xy}
(0,0)*[o]+{v_{3}}="3",(20,0)*[o]+{u}="u",(10,-15)*[o]+{v_{1}}="1",(30,-15)*[o]+{\circ}="000",(40,0)*[o]+{\circ}="001",(50,0)*[o]+{}="dammy1",
(55,0)*[o]+{\cdots}="cdots",(60,0)*[o]+{}="dammy2",(70,0)*[o]+{\circ}="002",(90,0)*[o]+{v_{2}}="2"
