In subsequent subsections, we examine when a modified Brauer tree algebra or the trivial extension of 
a tilted algebra of Dynkin type admits a cellular algebra structure.

\remark 
In \cite[Proposition 5.3]{KX1}, 
Brauer trees are allowed to have an arbitrary number of exceptional vertices. 
However, in the above classification of nonsimple basic standard symmetric algebras of finite type, 
we consider only  Brauer trees with at most one exceptional vertex $S$. 



\para 
\label{F BD}
We consider a modified Brauer tree algebra $D(T_S)$. 
By the definition of $D(T_S)$, 
if the Brauer tree $T_S$ has a branch, 
then the quiver of $D(T_S)$ contains a cycle whose length is at least $3$, 
and this cycle has no inverse arrow. 
This contradicts Proposition \ref{C Prop simple} (\roman{san}) if $D(T_S)$ is cellular. 
Thus, we see that 
the Brauer tree $T_S$ is a straight line if $D(T_S)$ is cellular.   

Suppose that the Brauer tree $T_S$ is a straight line with $n$ edges. 
Then the quiver $Q_{T_S}$ of $D(T_S)$ is given by 
\begin{align}
\label{F QTS}
\xymatrix{
Q_{T_S} = & 1 \ar@(ul,dl)_{\g } \ar[r]<0.5 ex>^{\a_1}  & 2 \ar[r]<0.5 ex>^{\a_2}   \ar[l]<0.5 ex>^{\b_1} 
	& 3 \ar[r]<0.5 ex>^{\a_3}  \ar[l]<0.5 ex>^{\b_2} & \cdots \ar[r]<0.5ex>^{\a_{n-1}} \ar[l]<0.5 ex>^{\b_3} 
		& n \ar[l]<0.5 ex>^{\b_{n-1}}.
} 
\end{align} 
We define $I_{T_S}$ to be the two-sided ideal of $K Q_{T_S}$ generated by 
\begin{align}
\label{F ITS}
\begin{split}
&\a_i \a_{i+1}, \, \b_{i+1} \b_i \, (1 \leq i \leq n-2), \, 
\b_1 \a_1, \, \a_{n-1} \b_{n-1} \a_{n-1}, \, \b_{n-1} \a_{n-1} \b_{n-1}, \, 
\\
&\g^2 - \a_1 \b_1, \, \a_2 \b_2 - \b_1 \g \a_1, \, \b_i \a_i - \a_{i+1} \b_{i+1}\, (2 \leq  i \leq n-2). 
\end{split}
\end{align}
Then we have $D(T_S) = K Q_{T_S} / I_{T_S}$. 
In the case where $n=2$, we have the following lemma.

\begin{proof}
Recall that $A(\lambda)=KQ/I$, where 
\[Q=\begin{xy}
(0,0)*[o]+{1}="1",
\SelectTips{eu}{}
\ar @(lu,ld)"1";"1"_{\alpha}
\ar @(ru,rd)"1";"1"^{\beta}
\end{xy}\] 
and $I$ is the admissible ideal generated by $\alpha^{2},$ $\beta^{2},$ $\alpha\beta-\lambda\beta\alpha$.

If $\lambda=1$, then $A(1)$ is cellular. 
Suppose that $A(\lambda)$ is a cellular algebra with cell datum $(\Lambda,\cT,\cC,\iota)$. 
Since $\lambda\neq 0$ and $A$ is local, $A(\lambda)$ is the unique indecomposable projective module, and its basis is given by
\[ A(\la) = Ke_1\oplus K\alpha \oplus K\beta\oplus K\alpha\beta. \]
Thus, the Cartan matrix of $A(\lambda)$ is $(4)$. 
Let $\bD$ be the decomposition matrix of $A(\lambda)$. 
By (i) and (iii) from Proposition \ref{C Prop decom matrix}, we have 
$\bD=(1\ 1\ 1\ 1)^T$. It implies that $\Lambda=\{\lambda_1, \lambda_2, \lambda_3, \lambda_4\}$ and 
we may assume without loss of generality that $\lambda_1$ is minimal in the partial order, and we may extend the partial order 
to the total order $1 < 2 < 3 < 4$. The equality $\dim A(\lambda)=\sum_{i=1}^4 |\cT(\lambda_i)|^{2}$ implies that we may set
\[ \cT(\lambda_1)=\cT(\lambda_2)=\cT(\lambda_3)=\cT(\lambda_4)=\{1\}. \]
The cellular basis is $\cC=\{c^{\lambda_i}_{1,1}\ |\ i=1,2,3,4\}$ and $\iota(c^{\lambda_i}_{1,1})=c^{\lambda_i}_{1,1}$
implies that the anti-involution $\iota$ fixes all elements of $A(\lambda)$. It follows that
\[ \alpha\beta=\iota(\alpha\beta)=\iota(\lambda\beta\alpha)=\lambda\iota(\alpha)\iota(\beta)=\lambda\alpha\beta. \]
Therefore, we obtain $\lambda=1$.
\end{proof}



\para
Next, we consider the non-local case. We begin by the algebras $\Lambda'(T)$ from Definition \ref{D defn I}.
Suppose that the Brauer graph has a cycle which is not a loop. 
Since $T$ does not have a loop, Proposition \ref{C Prop simple}(iii) implies that $T$ does not have a branch. 
Hence, $T$ coincides with the cycle of odd length. Its Brauer quiver $Q_{T}$ is given by
\[
\begin{xy}
(0,11)*[o]+{1}="0",(15,5)*[o]+{2}="1",(20,-8)*[o]+{3}="2", (-15,5)*[oo]+{2n+1}="3",(-20,-8)*[o]+{2n}="4",
(17,-20)*[o]+{4}="5",(0,-30)*{}="dammy",
\ar @<1mm> "0";"1"^{\alpha_1}
\ar @<1mm> "1";"0"^{\alpha_2}
\ar @<1mm> "1";"2"^{\beta_2}
\ar @<1mm> "2";"1"^{\beta_3}
\ar @<1mm> "0";"3"^{\gamma_{1}}
\ar @<1mm> "3";"0"^{\gamma_{2n+1}}
\ar @<1mm> "4";"3"^{\beta_{2n}}
\ar @<1mm> "3";"4"^{\beta_{2n+1}}
\ar @<1mm> "2";"5"^{\alpha_{3}}
\ar @<1mm> "5";"2"^{\alpha_{4}}
\ar @{--}@(l,d) "dammy";"4"
\ar @{--}@(l,d) "dammy";"5"
\end{xy}
\]
and the admissible ideal is generated by the following elements.
\begin{enumerate}
\item $\alpha_{2k-1}\beta_{2k}$, $\beta_{2k+1}\alpha_{2k}$, for $1\leq k\leq n$, 
\item $\alpha_{2k+1}\alpha_{2k+2}-\beta_{2k+1}\beta_{2k}$, for $1\leq k\leq n-1$,
\item$\beta_{2n}\gamma_{2n+1}$, $\gamma_1\beta_{2n+1}$, $\gamma_{2n+1}\alpha_1$ and $\alpha_2\gamma_1$, 
\item $\alpha_{2k}\alpha_{2k-1}-\beta_{2k}\beta_{2k+1}$, for $1\leq k\leq n$,
\item $\alpha_{1}\alpha_{2}-\gamma_{1}\gamma_{2n+1}$ and $\beta_{2n+1}\beta_{2n}-\gamma_{2n+1}\gamma_{1}$.
\end{enumerate}

\begin{proof}
We see that the Cartan matrix of $\Lambda'(T)$ is
\[ \bC = \begin{pmatrix}
2 & 1 & 0 & 0 & \cdots & 0 & 0 & 0 & 1 \\ 
1 & 2 & 1 & 0 & \cdots & 0 & 0 & 0 & 0 \\
0 & 1 & 2 & 1 & \cdots & 0 & 0 & 0 & 0 \\ 
 &  &  &  & \vdots &  &  &  &  \\ 
0 & 0 & 0 & 0 & \cdots & 0 & 1 & 2 & 1 \\ 
1 & 0 & 0 & 0 & \cdots & 0 & 0 & 1 & 2 
\end{pmatrix}. \]
The same Cartan matrix appeared in the proof of Proposition \ref{F Prop hatQ hatI} and 
the argument there shows that $\Lambda'(T)$ cannot be cellular.
\end{proof}


\para
Suppose that the Brauer graph has a loop. Then, Proposition \ref{C Prop simple}(iii) implies that
the Brauer graph $T$ is of the form:
\begin{equation}
\label{D I-2 Brauer graph}
\begin{xy}
(0,0)*[o]+{\circ}="0",(10,0)*[o]+{\circ}="1",(20,0)*[o]+{\circ}="2", (30,0)*[o]+{\cdots}="d1",(40,0)*[o]+{\circ}="3",
(50,0)*[o]+{v}="v",(60,0)*[o]+{\circ}="4",(70,0)*[o]+{\circ}="5", (80,0)*[o]+{\cdots}="d3",(90,0)*[o]+{\circ}="6",
(-10,0)*{}="dammy",(100,0)*[o]+{\circ}="7"
\ar @{-}"0";"1"^{-l}
\ar @{-}"1";"2"^{-(l-1)}
\ar @{-}"2";"d1"
\ar @{-}"d1";"3"
\ar @{-}"3";"v"^{-1}
\ar @{-}"v";"4"^{1}
\ar @{-}"4";"5"^{2}
\ar @{-}"5";"d3"
\ar @{-}"d3";"6"
\ar @{-}"6";"7"^{m}
\ar @{-} @(u,u)"v";"dammy"_{0}
\ar @{-} @(d,d)"dammy";"v"
\end{xy}
\end{equation}
with no exceptional vertex.
We denote the above Brauer graph by $T(l,m)$. We introduce the corresponding Brauer quiver as follows.

\begin{definition}
For $l,m\geq 0$, we denote the following quiver by $Q(l,m)$.
\[
\begin{xy}
(-55,0)*[o]+{-l}="-l",(-43,0)*[o]+{}="-l+1", (-40,0)*{\cdots}="d1",(-36,0)*{}="-3",(-25,0)*[o]+{-2}="-2",(-12,0)*[o]+{-1}="-1",
(0,0)*[o]+{0}="0",(10,0)*[o]+{1}="1",(20,0)*[o]+{2}="2", (30,0)*[o]+{}="3",(34,0)*{\cdots}="d1",(38,0)*[o]+{}="m-1",
(50,0)*[o]+{m}="m"
\ar @<1mm> "-l";"-l+1"^{\alpha_{-l}}
\ar @<1mm> "-l+1";"-l"^{\beta_{-l+1}}
\ar @<1mm> "-3";"-2"^{\alpha_{-3}}
\ar @<1mm> "-2";"-3"^{\beta_{-2}}
\ar @<1mm> "-2";"-1"^{\alpha_{-2}}
\ar @<1mm> "-1";"-2"^{\beta_{-1}}
\ar @<1mm> "-1";"0"^{\delta_{-1}}
\ar @<1mm> "0";"-1"^{\delta_{0}}
\ar @<1mm> "0";"1"^{\gamma_{0}}
\ar @<1mm> "1";"0"^{\gamma_{1}}
\ar @<1mm> "1";"2"^{\alpha_{1}}
\ar @<1mm> "2";"1"^{\beta_{2}}
\ar @<1mm> "2";"3"^{\alpha_{2}}
\ar @<1mm> "3";"2"^{\beta_{3}}
\ar @<1mm> "m-1";"m"^{\alpha_{m-1}}
\ar @<1mm> "m";"m-1"^{\beta_{m}}
\SelectTips{eu}{}
\ar @(dl,ul)"-l";"-l"^{\beta_{-l}}
\ar @(ur,dr)"m";"m"^{\alpha_m}
\end{xy}
\]
Here, $\beta_{0}=\delta_{0}$ if $l=0$ and $\alpha_0=\gamma_0$ if $m=0$. 
We label arrows other than the $\gamma$-cycle and the $\delta$-cycle with $\alpha_i$ and $\beta_i$, but 
we do not follow the convention to divide the arrows into $\alpha$-parts and $\beta$-parts in such a way that 
each of the relevant vertices of the Brauer graph is the intersection of an $\alpha$-cycle and a $\beta$-cycle.
\end{definition}

We write $\Lambda'(T(l,m))=KQ(l,m)/I$ and recall the generators of the ideal $I$ for the following five cases. 
Then, from those explicit generators, it is easy to see that $\Lambda'(T(l,m))\cong \Lambda'(T(m,l))$, so that the five cases suffice. 

\begin{enumerate}
\item[(a)] $m\ge l\ge 2$ or $m>l\geq 1$.
\item[(b)] $m=l=1$.
\item[(c)] $l=0$, $m>1$.
\item[(d)] $l=0$, $m=1$.
\item[(e)] $l=m=0$.
\end{enumerate}


\para
Suppose that we are in the case (a). Then $I$ is the ideal generated by the following elements:
\begin{enumerate}
\item $\alpha_i\alpha_{i+1}$, for $-l\leq i\leq -3$ or $1\leq i\leq m-1$ (if $l=1$, then $1\leq i\leq m-1$), 
\item $\beta_i\beta_{i-1}$, for $-l+1\leq i\leq -1$ or $3\leq i\leq m$ (if $l=1$, then $3\leq i\leq m$), 
\item $\alpha_m\beta_m$, $\gamma_0\alpha_1$, $\beta_2\gamma_1$ and $\delta_0\beta_{-1}$,
\item $\beta_{-l}\alpha_{-l}$, $\alpha_{-2}\delta_{-1}$ (if $l=1$, then $\beta_{-1}\delta_{-1}$),
\item $\alpha_i\beta_{i+1}-\beta_i\alpha_{i-1}$, for $-l+1\leq i\leq -2$ or $2\leq i\leq m-1$ (if $l=1$, then $2\leq i\leq m-1$), 
\item $\alpha_m-\beta_m\alpha_{m-1}$ and $\beta_{-l}-\alpha_{-l}\beta_{-l+1}$, (if $l=1$, then $\beta_{-l}-\alpha_{-l}\beta_{-l+1}$ does not occur.)
\item $\alpha_{1}\beta_{2}-\gamma_{1}\delta_{0}\delta_{-1}\gamma_{0}$,
\item $\beta_{-1}\alpha_{-2}-\delta_{-1}\gamma_0\gamma_1\delta_0$ (if $l=1$, then $\beta_{-1}-\delta_{-1}\gamma_0\gamma_1\delta_0$),
\item $\gamma_{1}\gamma_{0}$, $\delta_{-1}\delta_{0}$, $\gamma_{0}\gamma_{1}\delta_{0}\delta_{-1}-\delta_{0}\delta_{-1}\gamma_{0}\gamma_{1}$.
\end{enumerate}
By using (vi) or (viii), we delete the arrows $\alpha_{m}$ and $\beta_{-l}$ from $Q(l,m)$ 
to obtain the Gabriel quiver, 
and replace $\alpha_m$ (respectively, $\beta_{-l}$) in the above generators of $I$ with 
$\beta_m\alpha_{m-1}$ (respectively, $\alpha_{-l}\beta_{-l+1}$ or $\delta_{-1}\gamma_0\gamma_1\delta_0$ if $l=1$). 
Explicit computation shows that the indecomposable projective modules are given by
\[\begin{array}{lcl}
P_{-l} &=& Ke_{-l}\oplus K\beta_{-l+1} \oplus K\alpha_{-l}\beta_{-l+1} \;\text{(if $l\ge 2$)}, \\
P_{i} &=& Ke_{i} \oplus  K\alpha_{i-1} \oplus K\beta_{i+1}\oplus K\alpha_{i}\beta_{i+1} \quad (i\notin \{-l, -1,0,1,m\}), \\
P_{-1} &=& \begin{cases}
Ke_{-1}\oplus K\alpha_{-2}\oplus K\delta_{0} \oplus K\gamma_{1}\delta_{0}
\oplus K\gamma_{0}\gamma_{1}\delta_{0} \oplus K\delta_{-1}\gamma_{0}\gamma_1\delta_0 \;&\text{(if $l\ge2$)},\\
Ke_{-1}\oplus K\delta_{0} \oplus K\gamma_{1}\delta_{0}
\oplus K\gamma_{0}\gamma_{1}\delta_{0} \oplus K\delta_{-1}\gamma_{0}\gamma_1\delta_0 \;&\text{(if $l=1$)},
\end{cases}\\
P_{0} &=& Ke_0\oplus K\delta_{-1}\oplus K\gamma_{1} \oplus K\delta_{0}\delta_{-1} \oplus K\gamma_{0}\gamma_{1}\oplus K\gamma_{1}\delta_{0}\delta_{-1} \\
        & & \oplus K\delta_{-1}\gamma_{0}\gamma_{1}\oplus K\gamma_0\gamma_1\delta_0\delta_{-1}, \\
P_1  &=& Ke_1\oplus K\beta_2\oplus K\gamma_0\oplus K\delta_{-1}\gamma_0\oplus K\delta_{0}\delta_{-1}\gamma_0\oplus K\gamma_{1}\delta_0\delta_{-1}\gamma_{0}, \\
P_m &=& Ke_m\oplus K\alpha_{m-1} \oplus K\beta_m\alpha_{m-1}.     
\end{array} \]

Suppose that we are in the case (b). Then $I$ is the ideal generated by the following elements:
\begin{enumerate}
\item  $\alpha_1\gamma_1$, $\gamma_0\alpha_1$, $\beta_{-1}\delta_{-1}$ and $\delta_0\beta_{-1}$, 
\item $\alpha_{1}-\gamma_{1}\delta_{0}\delta_{-1}\gamma_{0}$ and $\beta_{-1}-\delta_{-1}\gamma_0\gamma_1\delta_0$,
\item $\gamma_{1}\gamma_{0}$, $\delta_{-1}\delta_{0}$, $\gamma_{0}\gamma_{1}\delta_{0}\delta_{-1}-\delta_{0}\delta_{-1}\gamma_{0}\gamma_{1}$.
\end{enumerate}
By using (ii), we delete the arrows $\alpha_{1}$ and $\beta_{-1}$ from $Q(1,1)$ to obtain the Gabriel quiver  
and replace $\alpha_1$ (respectively, $\beta_{-1}$) in the above generators of $I$ 
by $\gamma_{1}\delta_{0}\delta_{1}\gamma_{0}$ (respectively, $\delta_{-1}\gamma_0\gamma_1\delta_0$). 
Explicit computation shows 
\[\begin{array}{lcl}
P_{-1} &=&Ke_{-1}\oplus K\delta_{0}\oplus K\gamma_1\delta_{0} \oplus K\gamma_0\gamma_{1}\delta_{0}\oplus K\delta_{-1}\gamma_{0}\gamma_{1}\delta_{0}, \\
P_{0} &=& Ke_0\oplus K\delta_{-1}\oplus K\gamma_{1} \oplus K\delta_{0}\delta_{-1} \oplus K\gamma_{0}\gamma_{1}\oplus K\gamma_{1}\delta_{0}\delta_{-1} \\
        & & \oplus K\delta_{-1}\gamma_{0}\gamma_{1}\oplus K\gamma_0\gamma_1\delta_0\delta_{-1}, \\
P_1  &=& Ke_1\oplus K\gamma_0\oplus K\delta_{-1}\gamma_0\oplus K\delta_{0}\delta_{-1}\gamma_0\oplus K\gamma_{1}\delta_0\delta_{-1}\gamma_{0}. \\   
\end{array} \]

\para
We consider the algebras $\Gamma^{(0)}(T,v)$ from Definition \ref{D defn II}. Then, by Proposition \ref{C Prop simple}(iii), 
the Brauer graph $T$ is one of the following $T(m)$ or $T(-m)$:
\[
\label{D II Brauer graph}
T(m)=\begin{xy}
(0,0)*[o]+{v}="3", (10,0)*[o]+{u}="v",(20,0)*[o]+{\circ}="4", (30,0)*[o]+{\cdots}="d3",(40,0)*[o]+{\circ}="6",
(-5,0)*{}="dammy",(50,0)*[o]+{\circ}="7"
\ar @{-}"3";"v"^{a}
\ar @{-}"v";"4"^{1}
\ar @{-}"4";"d3"
\ar @{-}"d3";"6"
\ar @{-}"6";"7"^{m}
\ar @{-} @(u,u)"v";"dammy"_{b}
\ar @{-} @(d,d)"dammy";"v"
\end{xy} \;\; T(-m)=\begin{xy}
(0,0)*[o]+{\circ}="0",(10,0)*[o]+{\circ}="1",(20,0)*[o]+{\cdots}="d1",(30,0)*[o]+{\circ}="3",
(40,0)*[o]+{u}="v",(50,0)*[o]+{v}="4",
(-5,0)*{}="dammy",
\ar @{-}"0";"1"^{m}
\ar @{-}"1";"d1"
\ar @{-}"d1";"3"
\ar @{-}"3";"v"^{1}
\ar @{-}"v";"4"^{a}
\ar @{-} @(u,u)"v";"dammy"_{b}
\ar @{-} @(d,d)"dammy";"v"
\end{xy}
\]
where $m\ge 1$. The defining relations for $\Gamma^{(0)}(T(m),v)$, which we will give below, show that  
there exists an isomorphism of algebras $\Gamma^{(0)}(T(m),v)\cong \Gamma^{(0)}(T(-m),v)$. 
Hence, it suffices to consider $T=T(m)$ for $m\ge 1$. We denote the corresponding Brauer quiver by $Q(m)$, which we label 
the arrows as follows:
\[
\begin{xy}
(-12,0)*[o]+{a}="-1",
(0,0)*[o]+{b}="0",(10,0)*[o]+{1}="1",(20,0)*[o]+{2}="2", (30,0)*[o]+{}="3",(34,0)*{\cdots}="d1",(38,0)*[o]+{}="m-1",
(50,0)*[o]+{m}="m"
\ar @<1mm> "-1";"0"^{\delta_a}
\ar @<1mm> "0";"-1"^{\delta_b}
\ar @<1mm> "0";"1"^{\gamma_b}
\ar @<1mm> "1";"0"^{\gamma_{1}}
\ar @<1mm> "1";"2"^{\alpha_{1}}
\ar @<1mm> "2";"1"^{\beta_{2}}
\ar @<1mm> "2";"3"^{\alpha_{2}}
\ar @<1mm> "3";"2"^{\beta_{3}}
\ar @<1mm> "m-1";"m"^{\alpha_{m-1}}
\ar @<1mm> "m";"m-1"^{\beta_{m}}
\SelectTips{eu}{}
\ar @(ul,dl)"-1";"-1"_{\alpha_a}
\ar @(ur,dr)"m";"m"^{\alpha_m}
\end{xy}
\]

Suppose that $m>1$. Then $\Gamma^{(0)}(T(m),v)=KQ(m)/I$, where $I$ is the ideal generated by the following elements:
\begin{enumerate}
\item $\alpha_{i}\alpha_{i+1}$, for $1\leq i\leq m-1$, 
\item $\beta_{i}\beta_{i-1}$, for $3\leq i\leq m$, 
